    "statement": "Uma gestante manifesta interesse em entregar seu recém-nascido para adoção antes ou logo após o parto (\"entrega voluntária\"), ou um padrasto pretende adotar a filha de sua esposa (adoção unilateral). Em quais hipóteses o Art. 50, § 13, do ECA admite adoção por pessoa NÃO cadastrada previamente no SNA (Sistema Nacional de Adoção)?",
