    "justification": "Entrega voluntária (Art. 19-A): legal, assistida, sigilosa; retratação até audiência ou 10 dias pós-sentença (Art. 166, § 5º). Fura-fila permitido SÓ nas 3 hipóteses do Art. 50, § 13: unilateral (padrasto/madrasta), parente com vínculo ou tutor/guardião legal de criança > 3 anos.",
